{"content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Maps the positional CLI syntax onto configuration keys. The syntax is a caller contract
/// (F-428 P12.13 brief §4): <c>census &lt;trace.jsonl&gt;</c> and
/// <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>. Anything else yields an empty dictionary,
/// which the runner turns into a usage error and exit 1.
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>Parses <paramref name="args"/> into configuration key/value pairs.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <returns>Bound keys under the <see cref="AutoWrongCensusOptions.SectionName"/> section; empty when the invocation is unusable.</returns>
	public static Dictionary<string, string> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 0)
		{
			return dict;
		}

		var command = args[0];
		if (command.Equals("--help", StringComparison.OrdinalIgnoreCase) || command.Equals("-h", StringComparison.OrdinalIgnoreCase))
		{
			return dict;
		}

		if (command.Equals("census", StringComparison.OrdinalIgnoreCase) && args.Length == 2)
		{
			dict[$"{AutoWrongCensusOptions.SectionName}:Command"] = "census";
			dict[$"{AutoWrongCensusOptions.SectionName}:TracePath"] = args[1];
		}
		else if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase) && args.Length == 3)
		{
			dict[$"{AutoWrongCensusOptions.SectionName}:Command"] = "pairs";
			dict[$"{AutoWrongCensusOptions.SectionName}:CensusTsvPath"] = args[1];
			dict[$"{AutoWrongCensusOptions.SectionName}:TracePath"] = args[2];
		}

		return dict;
	}
}
