public static class AutoWrongCensusUsage
{
	/// <summary>Prints the usage text to stdout.</summary>
	public static void Print()
	{
		System.Console.WriteLine("""
			LetUsCook.AutoWrongCensus — F-428 P12.13 auto-wrong census

			Classifies every auto-wrong line (auto == true && correct == false) of a HoldoutGate
			trace JSONL on two axes: relation (accepted row vs labelled key row) and site (reuse,
			override, curated, ranker). It calls the production FdcNormalizer / FdcMatcher /
			FdcDescriptionParser / IngredientLineResolver helpers; it never re-implements them.

			Usage:
			  LetUsCook.AutoWrongCensus census <trace.jsonl>
			    TSV (columns: holdoutId lineIndex set relation site overrideKey acceptedTier keyTier
			    acceptedState keyState parsedName keyHead acceptedDesc keyDesc rawText) to stdout;
			    the relation x site summary to stderr. Exits 1 on a missing trace or a trace whose
			    set is not debug or batch (D-029: no sealed read).

			  LetUsCook.AutoWrongCensus pairs <census.tsv> <trace.jsonl>
			    For each row of the P12.7 blocker census with blocker = window and route compound
			    or other, emits the parsedName head and the key head-word pair (TSV) to stdout.
			""");
	}
}
