{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies one auto-wrong trace line on two axes — <em>relation</em> (how the accepted
/// row differs from the labelled key row) and <em>site</em> (which decision path accepted it).
/// <para>
/// Every comparison runs the production helpers (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>
/// for tokens, <see cref="FdcMatcher.ExtractCandidateState"/> + <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
/// for state masks, <see cref="FdcDescriptionParser.Parse"/> for head terms,
/// <see cref="IngredientLineResolver.SingularizeToken"/> for singularisation,
/// <see cref="IngredientLineResolver.ShouldReuse"/> for the reuse-rule summary, and the
/// <see cref="FdcLexicon.ModifierWords"/> lexicon for the compound-head cut (brief §4: the key's head
/// phrase is its leading tokens, truncated before the first token the production state machinery or
/// the modifier lexicon names — "Bread, crumbs, dry, grated, plain" → "bread crumbs").
/// </para>
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: the raw line names a can/jar unit, the key row is Canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase is multi-word and the parsed name kept only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the production state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the accepted row sits on another dataset tier.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree; the rows differ only in qualifier words.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: no specific shape held, or a needed trace field was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the resolver reused an existing master row (path ranker, reused).</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact/special-case override path (path override).</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue shortcut (path curated).</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker accepted a fresh row (path ranker, not reused).</summary>
	public public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token carrier for the per-token state probe; the classifier is single-threaded.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates a classifier over the production normalizer and the exact-overrides key set.</summary>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The relation ladder (brief §4, first match wins):
	/// no-label → pack-unit-state → compound-head-lost → state-mismatch → row-choice-tier →
	/// same-head-other-qualifier → sibling-food → other (a missing field a step needed also lands here,
	/// named in <see cref="ClassificationResult.MissingField"/>).
	/// </summary>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;

		var site = atom is null ? null : SiteOf(atom);
		var overrideKey = site == SiteOverride ? (_overrideKeys.Contains(OverrideLookupKey(line.RawText)) ? "yes" : "no") : string.Empty;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return Build(line, NoLabel, site, overrideKey, acceptedTier, keyTier, FoodState.None, FoodState.None, parsedName, string.Empty, acceptedDesc, keyDesc, null);
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedParsed.HeadTerm);
		var parsedTokens = SingularPhrase(parsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var relation = ClassifyRelation(
			line.RawText, keyDesc, acceptedDesc, keyTier, acceptedTier, keyState, acceptedState, keyHead, acceptedHead, parsedTokens, keyPhrase,
			out string? missingField);

		var keyHeadText = string.Join(' ', keyPhrase);
		return Build(line, relation, site, overrideKey, acceptedTier, keyTier, acceptedState, keyState, parsedName, keyHeadText, acceptedDesc, keyDesc, missingField);
	}

	/// <summary>
	/// The key's head phrase: the key description's normalized tokens up to the first token the
	/// production state machinery or the modifier lexicon names. "Bread, crumbs, dry, grated, plain"
	/// → [bread, crumbs]; "Tomatoes, crushed, canned" → [tomato]; "Nuts, almonds, blanched" → [nut, almond].
	/// </summary>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		for (var i = 0; i < keyTokens.Count; i++)
		{
			if (NamesState(keyTokens[i]))
			{
				break;
			}

			phrase.Add(keyTokens[i]);
		}

		return phrase;
	}

	/// <summary>The production state+satisfier mask for a token list — the same composition FdcMatcher feeds StateAgrees.</summary>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string? SiteOf(TraceAtom atom) => atom.Path switch
	{
		"override" => SiteOverride,
		"curated" => SiteCurated,
		"ranker" => atom.Reused ? SiteReuse : SiteRanker,
		_ => null,
	};

	private string ClassifyRelation(
		string rawText, string keyDesc, string acceptedDesc, string keyTier, string acceptedTier,
		FoodState keyState, FoodState acceptedState,
		IReadOnlyList<string> keyHead, IReadOnlyList<string> acceptedHead,
		IReadOnlyList<string> parsedTokens, IReadOnlyList<string> keyPhrase,
		out string? missingField)
	{
		missingField = null;

		// 1. no-label is decided in Classify (empty key row).
		// 2. pack-unit-state: a can/jar unit in the raw line, Canned on the key, absent on the accepted row.
		if (PackUnitRegex().IsMatch(rawText) && (keyState & FoodState.Canned) != 0 && (acceptedState & FoodState.Canned) == 0)
		{
			return PackUnitState;
		}

		// 3. compound-head-lost: the key's head phrase is multi-word and the parsed name kept only its first word.
		if (keyPhrase.Count >= 2 && parsedTokens.Count == 1 &&
			string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			return SiblingFood;
		}

		// 4. state-mismatch.
		if (keyState != acceptedState)
		{
			return StateMismatch;
		}

		// 5. row-choice-tier needs both tiers; a missing one is an "other" with the field named (brief §8).
		if (string.IsNullOrWhiteSpace(acceptedTier) || string.IsNullOrWhiteSpace(keyTier))
		{
			missingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
			return Other;
		}

		if (!string.Equals(acceptedTier, keyTier, StringComparison.OrdinalIgnoreCase))
		{
			return RowChoiceTier;
		}

		// 6. same-head-other-qualifier (head, state and tier all agree).
		return SameHeadOtherQualifier;
	}

	private bool NamesState(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	/// <summary>
	/// The override-lookup key the production matcher builds for a raw line (FdcMatcher.MatchAsync:
	/// strip at the first parenthesis, trim, lowercase — StripFromParenthesis is private, so the
	/// equivalent cut is applied here; the key set itself is the production exact-overrides.json).
	/// </summary>
	public static string OverrideLookupKey(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

#pragma warning disable CA1308 // Lowercase folding, parity with FdcMatcher's nameClean.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	private static ClassificationResult Build(
		TraceLine line, string? relation, string? site, string overrideKey,
		string acceptedTier, string keyTier, FoodState acceptedState, FoodState keyState,
		string parsedName, string keyHead, string acceptedDesc, string keyDesc, string? missingField)
		=> new(
			line.HoldoutId, line.LineIndex, line.Set,
			relation ?? Other, site ?? "unknown-site", overrideKey,
			acceptedTier, keyTier,
			acceptedState.ToString(), keyState.ToString(),
			parsedName, keyHead, Sanitize(acceptedDesc), Sanitize(keyDesc), Sanitize(line.RawText), missingField);

	private static string Sanitize(string text) =>
		text.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
