{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines — <b>relation</b>
/// (accepted row vs key row) and <b>site</b> (where the row was accepted) — using only the production
/// helpers (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FoodState"/>, <see cref="FdcDescriptionParser.Parse"/> and
/// <see cref="IngredientLineResolver.SingularizeToken"/>. No matcher logic is re-implemented here.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: rawText carries a can/jar unit, the key row is <see cref="FoodState.Canned"/> and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsedName equals only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree after singularising and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tiers differ.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state agree, tiers agree, nothing above holds.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: no rule above held, or a field a rule needed was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing master/row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact/special-case override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Reused single-token probe list for the per-token state checks (avoids per-token allocation).</summary>
	private readonly List<string> _singleToken = new();

	/// <summary>Creates a classifier.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">The exact-overrides key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The relation rules run in the brief's order — first that holds
	/// wins: no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier,
	/// same-head-other-qualifier, sibling-food, other.
	/// </summary>
	/// <param name="line">One trace line with <c>auto == true && correct == false</c>.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var site = ClassifySite(atom, line.RawText);
		var overrideKey = site.Equals(SiteOverride, StringComparison.Ordinal)
			? (_overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no")
			string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedParsed.HeadTerm);
		var parsedNameTokens = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = Other;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (string.IsNullOrWhiteSpace(acceptedDesc))
		{
			relation = Other;
			missingField = "actualDescriptions";
		}
		else if (HeadsAgree(keyHead, acceptedHead))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				relation = Other;
				missingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				keyOnlyQualifiers = QualifierDiff(keyParsed.Qualifiers, acceptedParsed.Qualifiers, keySide: true);
				acceptedOnlyQualifiers = QualifierDiff(keyParsed.Qualifiers, acceptedParsed.Qualifiers, keySide: false);
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key row's normalized tokens from the start up to the first token that
	/// production treats as a state or modifier word. This is the "head" the compound-head-lost rule
	/// compares the parsedName against — for <c>"Bread, crumbs, dry, grated, plain"</c> it is
	/// <c>bread crumbs</c>, for <c>"Tomatoes, crushed, canned"</c> it is <c>tomato</c>.
	/// </summary>
	/// <param name="tokens">The key row's normalized tokens.</param>
	/// <returns>The head phrase tokens, each singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask of a token list: <see cref="FdcMatcher.ExtractCandidateState"/> ∪
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition the matcher feeds
	/// its <c>StateAgrees</c> checks.
	/// </summary>
	/// <param name="tokens">A normalized token list.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Tier rank for the <c>row-choice-tier</c> direction: Foundation &gt; SrLegacy &gt; Survey &gt; Branded.</summary>
	/// <param name="tier">A dataset tier name.</param>
	/// <returns>The rank; 0 for an unknown tier.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private string ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	/// <summary>
	/// Folds raw text the way the matcher folds it for the raw-key override lookup: lower-cased,
	/// trimmed, content from the first <c>(</c> dropped (the matcher's <c>StripFromParenthesis</c> is
	/// private; this is the same single cut).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
#pragma warning disable CA1308 // Reason: parity with FdcMatcher's lowercase folding for the override lookup.
		var lowered = rawText.Trim().ToLowerInvariant();
#pragma warning restore CA1308
		var index = lowered.IndexOf('(', StringComparison.Ordinal);
		return (index >= 0 ? lowered[..index] : lowered).Trim();
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static bool HeadsAgree(IReadOnlyList<string> left, IReadOnlyList<string> right)
	{
		if (left.Count != right.Count)
		{
			return false;
		}

		for (var i = 0; i < left.Count; i++)
		{
			if (!string.Equals(left[i], right[i], StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
		}

		return true;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateOrModifierWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static IReadOnlyList<string> QualifierDiff(IReadOnlyList<string> keyQualifiers, IReadOnlyList<string> acceptedQualifiers, bool keySide)
	{
		var key = new HashSet<string>(keyQualifiers, StringComparer.OrdinalIgnoreCase);
		var accepted = new HashSet<string>(acceptedQualifiers, StringComparer.OrdinalIgnoreCase);
		var source = keySide ? key : accepted;
		var other = keySide ? accepted : key;
		return source.Where(t => !other.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
	}
}
