{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies one auto-wrong trace line on two axes — <b>relation</b> (how the accepted
/// row differs from the labelled key row) and <b>site</b> (which decision produced the accepted row).
/// Every head/state/normalisation step calls the production helpers (<c>FdcNormalizer.NormalizeToTokens</c>,
/// <c>FdcMatcher.ExtractCandidateState</c>/<c>ExtractCandidateSatisfiers</c>, <c>FdcDescriptionParser.Parse</c>,
/// <c>IngredientLineResolver.SingularizeToken</c>, <c>IngredientLineResolver.ShouldReuse</c>) — never a copy (D-014).
/// </summary>
/// <remarks>
/// Not thread-safe: the per-token state probe reuses one scratch list. The runner classifies lines sequentially.
/// </remarks>
public sealed partial class AutoWrongClassifier
{
	/// <summary><c>no-label</c>: the line has no labelled (key) row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary><c>pack-unit-state</c>: a can/jar unit in the raw line, the key row is canned, the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary><c>compound-head-lost</c>: the key head phrase is multi-word and the parsed name is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary><c>state-mismatch</c>: the heads agree but the production state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary><c>row-choice-tier</c>: heads and state agree but the dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary><c>same-head-other-qualifier</c>: heads, state, and tier agree; only qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary><c>sibling-food</c>: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary><c>other</c>: no rule matched, or a trace field a rule needed was missing.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker chose the row fresh (no reuse).</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Trace sets the census may read; any other value is refused (D-029).</summary>
	public static readonly FrozenSet<string> AllowedSets =
		FrozenSet.ToFrozenSet(new[] { "debug", "batch" }, StringComparer.Ordinal);

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Scratch slot for the per-token state probe (single-threaded use).</summary>
	private readonly string?[] _singleTokenScratch = [null!];

	/// <summary>Creates a classifier over the production normalizer.</summary>
	/// <param name="normalizer">The production <c>FdcNormalizer</c>.</param>
	/// <param name="overrideKeys">The exact-overrides key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The relation rules run in the brief's fixed order, first hit wins:
	/// no-label → pack-unit-state → compound-head-lost → state-mismatch → row-choice-tier →
	/// same-head-other-qualifier → sibling-food → other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true</c> and <c>correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = acceptedDesc.Length > 0 ? FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)) : null;
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = acceptedParsed is null ? [] : SingularPhrase(acceptedParsed.HeadTerm);
		var parsedName = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var site = ClassifySite(atom, line.RawText);
		var overrideKey = site == SiteOverride
			? (_overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no")
			: string.Empty;

		var missingField = (string?)null;
		var relation = ClassifyRelation(
			line.RawText,
			keyDesc,
			acceptedDesc,
			keyTier,
			acceptedTier,
			keyState,
			acceptedState,
			keyHead,
			acceptedHead,
			parsedName,
			keyHeadPhrase,
			keyParsed,
			acceptedParsed,
			out missingField);

		var keyOnlyQualifiers = (IReadOnlyList<string>?)null;
		var acceptedOnlyQualifiers = (IReadOnlyList<string>?)null;
		if (relation == RelationSameHeadOtherQualifier)
		{
			var keyQualifiers = SingularPhraseList(keyParsed.Qualifiers);
			var acceptedQualifiers = acceptedParsed is null ? [] : SingularPhraseList(acceptedParsed.Qualifiers);
			keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key row's normalized tokens up to the first token the production
	/// vocabulary treats as a state/modifier word — the multi-word product head ("bread crumbs")
	/// without any lexicon of the census's own.
	/// </summary>
	/// <param name="keyTokens">The key row's normalized tokens.</param>
	/// <returns>The leading non-state tokens, in order.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		for (var i = 0; i < keyTokens.Count; i++)
		{
			if (CarriesStateToken(keyTokens[i]))
			{
				break;
			}

			phrase.Add(keyTokens[i]);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <c>ExtractCandidateState</c> ∪
	/// <c>ExtractCandidateSatisfiers</c> — the same composition the matcher feeds to <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">The normalized tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<c>ShouldReuse</c>) would match the parsed name
	/// against the linked master slug. Census statistic for reuse-site lines only.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug, or null.</param>
	/// <returns>True when the rule matches; false when it does not or the slug is absent.</returns>
	public bool ReuseRuleMatches(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	private string ClassifySite(TraceAtom? atom, string rawText)
	{
		var path = atom?.Path ?? string.Empty;
		return path.ToLowerInvariant() switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom!.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		string rawText,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		IReadOnlyList<string> parsedName,
		IReadOnlyList<string> keyHeadPhrase,
		ParsedFdcDescription keyParsed,
		ParsedFdcDescription? acceptedParsed,
		out string? missingField)
	{
		missingField = null;

		if (keyDesc.Trim().Length == 0)
		{
			return RelationNoLabel;
		}

		if (PackUnitRegex().IsMatch(rawText)
			&& (keyState & FoodState.Canned) == FoodState.Canned
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return RelationPackUnitState;
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedName.Count == 1
			&& string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return RelationCompoundHeadLost;
		}

		if (keyHead.Count == 0 && acceptedHead.Count == 0)
		{
			// Both sides parse to no head at all: no rule can compare them.
			return RelationOther;
		}

		if (!keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			return RelationSiblingFood;
		}

		if (keyState != acceptedState)
		{
			return RelationStateMismatch;
		}

		if (keyTier.Length == 0 || acceptedTier.Length == 0)
		{
			missingField = keyTier.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
			return RelationOther;
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return RelationRowChoiceTier;
		}

		return RelationSameHeadOtherQualifier;
	}

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>
	/// Folds a raw line for the exact-overrides lookup the same way production does: lower-cased,
	/// trimmed, content from the first <c>(</c> dropped (the matcher's private <c>StripFromParenthesis</c>
	/// is a single <c>IndexOf('(')</c> cut — reproduced here because it is not <c>internal</c>).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

#pragma warning disable CA1308 // Reason: parity with the matcher's lowercase override-lookup folding.
		return text.ToLowerInvariant().Trim();
#pragma warning restore CA1308
	}
}
