{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one <c>census</c> or <c>pairs</c> invocation against a HoldoutGate trace. The TSV goes to
/// the output sink (stdout by default); the relation × site summary and every refusal go to the
/// error sink. Exit 1 on a missing file, a refused set (D-029), or an unknown decision path.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	CensusWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions TraceJsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] AllowedSets = ["debug", "batch"];

	private const string TsvHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (opts.Command.Length == 0)
		{
			writers.Error.WriteLine("usage: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!File.Exists(opts.TracePath))
		{
			writers.Error.WriteLine($"refused: trace file not found at '{opts.TracePath}'.");
			return 1;
		}

		var lines = await ReadTraceAsync(opts, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		if (opts.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase))
		{
			return RunCensus(lines);
		}

		return await RunPairs(opts, lines, cancellationToken).ConfigureAwait(false);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var results = new List<ClassificationResult>(lines.Count);
		var unknownSite = 0;
		foreach (var line in lines)
		{
			if (!(line.Auto && !line.Correct))
			{
				continue;
			}

			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSite++;
				writers.Error.WriteLine($"refused: {line.HoldoutId}#{line.LineIndex} has unrecognised decision path '{line.Atoms.FirstOrDefault()?.Path}'.");
				continue;
			}

			results.Add(result);
		}

		if (unknownSite > 0)
		{
			writers.Error.WriteLine($"refused: {unknownSite} line(s) with an unrecognised decision path; no TSV emitted.");
			return 1;
		}

		writers.Output.WriteLine(TsvHeader);
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), r.LineIndex, Sanitize(r.Set), r.Relation, r.Site, r.OverrideKey,
				Sanitize(r.AcceptedTier), Sanitize(r.KeyTier), r.AcceptedState, r.KeyState,
				Sanitize(r.ParsedName), Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}

		WriteCensusSummary(lines, results);
		return 0;
	}

	private async Task<int> RunPairs(AutoWrongCensusOptions opts, IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(opts.CensusTsvPath))
		{
			writers.Error.WriteLine($"refused: census file not found at '{opts.CensusTsvPath}'.");
			return 1;
		}

		var censusRows = await Task.Run(() =>
		{
			var rows = new List<(string HoldoutId, int LineIndex)>();
			using var reader = new StreamReader(opts.CensusTsvPath);
			var header = reader.ReadLine()?.Split('\t') ?? [];
			var column = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
			for (var i = 0; i < header.Length; i++)
			{
				column[header[i]] = i;
			}

			if (!column.ContainsKey("holdoutId") || !column.ContainsKey("lineIndex") || !column.ContainsKey("blocker") || !column.ContainsKey("route"))
			{
				writers.Error.WriteLine($"refused: census file '{opts.CensusTsvPath}' lacks the holdoutId/lineIndex/blocker/route columns.");
				return null;
			}

			string? csvLine;
			while ((csvLine = reader.ReadLine()) is not null)
			{
				cancellationToken.ThrowIfCancellationRequested();
				var fields = csvLine.Split('\t');
				if (fields.Length < header.Length)
				{
					continue;
				}

				if (!fields[column["blocker"]].Equals("window", StringComparison.Ordinal)
					&& !(fields[column["route"]].Equals("compound", StringComparison.Ordinal) || fields[column["route"]].Equals("other", StringComparison.Ordinal)))
				{
					continue;
				}

				if (!int.TryParse(fields[column["lineIndex"]], out var lineIndex))
				{
					continue;
				}

				rows.Add((fields[column["holdoutId"]], lineIndex));
			}

			return rows;
		}, cancellationToken).ConfigureAwait(false);

		if (censusRows is null)
		{
			return 1;
		}

		var traceByLine = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var matched = 0;
		writers.Output.WriteLine(PairsHeader);
		foreach (var (holdoutId, lineIndex) in censusRows)
		{
			if (!traceByLine.TryGetValue((holdoutId, lineIndex), out var line))
			{
				writers.Error.WriteLine($"note: census row {holdoutId}#{lineIndex} has no trace line; skipped.");
				continue;
			}

			matched++;
			var parsedHead = string.Join(' ', FoldName(line.Atoms.FirstOrDefault()?.ParsedName ?? string.Empty));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.Normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			writers.Output.WriteLine(string.Join('\t', Sanitize(holdoutId), lineIndex, Sanitize(parsedHead), Sanitize(keyHead), Sanitize(line.RawText)));
		}

		writers.Error.WriteLine($"pairs: {matched}/{censusRows.Count} window compound/other census rows matched a trace line.");
		return 0;
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(AutoWrongCensusOptions opts, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		string? rejectedSet = null;
		try
		{
			using var reader = new StreamReader(opts.TracePath);
			string? traceLine;
			while ((traceLine = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false)) is not null)
			{
				if (traceLine.Trim().Length == 0)
				{
					continue;
				}

				var line = JsonSerializer.Deserialize<TraceLine>(traceLine, TraceJsonOptions);
				if (line is null)
				{
					writers.Error.WriteLine($"refused: trace line at character offset {reader.BaseStream.Position} is not a trace record.");
					return null;
				}

				if (rejectedSet is null && !AllowedSets.Contains(line.Set, StringComparer.Ordinal))
				{
					rejectedSet = line.Set;
				}

				lines.Add(line);
			}
		}
		catch (JsonException ex)
		{
			writers.Error.WriteLine($"refused: trace file '{opts.TracePath}' is not valid trace JSONL: {ex.Message}");
			return null;
		}

		if (rejectedSet is not null)
		{
			writers.Error.WriteLine($"refused: trace set '{rejectedSet}' is not debug or batch (D-029: no sealed reads).");
			return null;
		}

		return lines;
	}

	private void WriteCensusSummary(IReadOnlyList<TraceLine> lines, IReadOnlyList<ClassificationResult> results)
	{
		var sets = string.Join(',', lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).OrderBy(s => s, StringComparer.Ordinal));
		writers.Error.WriteLine($"autoWrongCensus set={sets} traced={lines.Count} autoWrong={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (Relation: g.Key.Relation, Site: g.Key.Site, Count: g.Count()))
			.OrderBy(x => x.Relation, StringComparer.Ordinal)
			.ThenBy(x => x.Site, StringComparer.Ordinal);
		writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var (relation, site, count) in matrix)
		{
			writers.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0):0.0}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		writers.Error.WriteLine(missing.Any() ? $"missingFields: {string.Join(' ', missing)}" : "missingFields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var checkedReuse = 0;
			var ruleAgreed = 0;
			foreach (var r in reuseLines)
			{
				var line = lines.FirstOrDefault(l => l.HoldoutId == r.HoldoutId && l.LineIndex == r.LineIndex);
				var atom = line?.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line?.Atoms.FirstOrDefault();
				if (atom is null || string.IsNullOrEmpty(atom.LinkedIngredientId) || string.IsNullOrWhiteSpace(atom.ParsedName))
				{
					continue;
				}

				checkedReuse++;
				if (IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					ruleAgreed++;
				}
			}

			writers.Error.WriteLine($"reuse-site ShouldReuse(parsedName, linkedIngredientId): agree={ruleAgreed}/{checkedReuse}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			writers.Error.WriteLine($"row-choice-tier: keyHigher={keyHigher} acceptedHigher={tierLines.Count - keyHigher}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualifier-diff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static IReadOnlyList<string> FoldName(string text) =>
		Array.ConvertAll(FdcNormalizer.Default.NormalizeToTokens(text).ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');
}
